param(
  [string]$DdlPath = (Join-Path $PSScriptRoot '..\..\mysql\ddl\001_ecommerce_oltp_candidate.sql'),
  [string]$ModelPath = (Join-Path $PSScriptRoot '..\..\docs\milestone-2-business-design.md')
)

$ErrorActionPreference = 'Stop'
$failures = [System.Collections.Generic.List[string]]::new()
function Assert-Contract([bool]$Condition, [string]$Message) { if (-not $Condition) { $script:failures.Add($Message) } }
function New-Map([string[]]$Entries) { $map = @{}; foreach ($entry in $Entries) { $parts = $entry.Split('|'); $map[$parts[0]] = $parts[1] }; return $map }
function Columns([string]$Text) { return (($Text.Split(',') | ForEach-Object { '`' + $_ + '`' }) -join ', ') }

foreach ($path in @($DdlPath, $ModelPath)) { Assert-Contract (Test-Path -LiteralPath $path) "Missing required input: $path" }
if ($failures.Count -gt 0) { $failures | ForEach-Object { Write-Error $_ }; exit 1 }
$ddl = Get-Content -LiteralPath $DdlPath -Raw -Encoding UTF8
$ddlWithoutComments = [regex]::Replace($ddl, '(?m)--.*$', '')
$model = Get-Content -LiteralPath $ModelPath -Raw -Encoding UTF8
$order = @('user_account','visitor','traffic_channel','brand','category','coupon','user_address','visit_session','spu','sku','user_coupon','login_event','page_view_event','cart_event','sales_order','sales_order_item','payment_attempt','return_order','refund_attempt')
$expectedCounts = @{ user_account=7; visitor=8; traffic_channel=7; brand=7; category=9; coupon=11; user_address=12; visit_session=9; spu=9; sku=10; user_coupon=17; login_event=7; page_view_event=11; cart_event=14; sales_order=19; sales_order_item=24; payment_attempt=15; return_order=17; refund_attempt=17 }
$expectedFks = New-Map @(
