)
$expectedUnique = New-Map @('uq_user_account_user_id|user_id','uq_visitor_visitor_id|visitor_id','uq_traffic_channel_channel_code|channel_code','uq_brand_brand_id|brand_id','uq_category_category_id|category_id','uq_coupon_coupon_id|coupon_id','uq_user_address_address_id|address_id','uq_visit_session_session_id|session_id','uq_spu_spu_id|spu_id','uq_sku_sku_id|sku_id','uq_user_coupon_user_coupon_no|user_coupon_no','uq_user_coupon_request_id|request_id','uq_login_event_login_event_id|login_event_id','uq_page_view_event_page_view_id|page_view_id','uq_cart_event_cart_event_id|cart_event_id','uq_cart_event_request_id|request_id','uq_sales_order_order_no|order_no','uq_sales_order_request_id|request_id','uq_sales_order_item_order_item_no|order_item_no','uq_sales_order_item_order_sku|order_pk,sku_pk','uq_payment_attempt_payment_no|payment_no','uq_payment_attempt_request_id|request_id','uq_payment_attempt_callback_request_id|callback_request_id','uq_payment_attempt_successful_order|successful_order_pk','uq_return_order_return_no|return_no','uq_return_order_request_id|request_id','uq_refund_attempt_refund_no|refund_no','uq_refund_attempt_request_id|request_id','uq_refund_attempt_callback_request_id|callback_request_id','uq_refund_attempt_successful_return_order|successful_return_order_pk')
$expectedIndexes = New-Map @('idx_user_account_registered|registered_at,user_account_pk','idx_user_account_incremental|update_time,user_account_pk','idx_visitor_first_seen|first_seen_at,visitor_pk','idx_visitor_incremental|update_time,visitor_pk','idx_traffic_channel_incremental|update_time,traffic_channel_pk','idx_brand_incremental|update_time,brand_pk','idx_category_parent_level_active|parent_category_pk,category_level,is_deleted,category_pk','idx_category_incremental|update_time,category_pk','idx_coupon_validity_active|valid_from,valid_to,is_deleted,coupon_pk','idx_coupon_incremental|update_time,coupon_pk','idx_user_address_user_active|user_pk,is_deleted,user_address_pk','idx_user_address_incremental|update_time,user_address_pk','idx_visit_session_visitor_started|visitor_pk,started_at','idx_visit_session_channel_started|first_channel_pk,started_at','idx_visit_session_incremental|update_time,visit_session_pk','idx_spu_brand_active|brand_pk,is_deleted,spu_pk','idx_spu_category_active|category_pk,is_deleted,spu_pk','idx_spu_incremental|update_time,spu_pk','idx_sku_spu_active|spu_pk,is_deleted,sku_pk','idx_sku_incremental|update_time,sku_pk','idx_user_coupon_user_status_valid|user_pk,coupon_status,valid_to,user_coupon_pk','idx_user_coupon_coupon_status|coupon_pk,coupon_status,user_coupon_pk','idx_user_coupon_status_valid|coupon_status,valid_to,user_coupon_pk','idx_user_coupon_incremental|update_time,user_coupon_pk','idx_login_event_user_login|user_pk,login_at','idx_login_event_visitor_login|visitor_pk,login_at','idx_login_event_session_login|session_pk,login_at','idx_login_event_incremental|create_time,login_event_pk','idx_page_view_event_session_event|session_pk,event_time','idx_page_view_event_visitor_event|visitor_pk,event_time','idx_page_view_event_user_event|user_pk,event_time','idx_page_view_event_channel_event|channel_pk,event_time','idx_page_view_event_type_event|page_type,event_time','idx_page_view_event_sku_event|sku_pk,event_time','idx_page_view_event_incremental|create_time,page_view_event_pk','idx_cart_event_visitor_action|visitor_pk,action_time','idx_cart_event_user_action|user_pk,action_time','idx_cart_event_session_action|session_pk,action_time','idx_cart_event_sku_action|sku_pk,action_time','idx_cart_event_incremental|create_time,cart_event_pk','idx_sales_order_user_ordered|user_pk,ordered_at','idx_sales_order_status_ordered|order_status,ordered_at','idx_sales_order_coupon_status|user_coupon_pk,order_status','idx_sales_order_incremental|update_time,sales_order_pk','idx_sales_order_item_sku|sku_pk,sales_order_item_pk','idx_sales_order_item_incremental|create_time,sales_order_item_pk','idx_payment_attempt_order_attempted|order_pk,attempted_at','idx_payment_attempt_status_attempted|payment_status,attempted_at','idx_payment_attempt_paid|paid_at,payment_attempt_pk','idx_payment_attempt_incremental|update_time,payment_attempt_pk','idx_return_order_item_applied|order_item_pk,applied_at','idx_return_order_order_applied|order_pk,applied_at','idx_return_order_status_completed|return_status,completed_at','idx_return_order_completed|completed_at,return_order_pk','idx_return_order_incremental|update_time,return_order_pk','idx_refund_attempt_return_attempted|return_order_pk,attempted_at','idx_refund_attempt_order_refunded|order_pk,refunded_at','idx_refund_attempt_payment_refunded|payment_attempt_pk,refunded_at','idx_refund_attempt_status_attempted|refund_status,attempted_at','idx_refund_attempt_incremental|update_time,refund_attempt_pk')
$expectedChecks = New-Map @('ck_cart_event_action_validity|`is_valid` IN (0, 1)','ck_page_view_event_page_sku|`page_type` IN (''HOME'', ''PRODUCT_DETAIL'', ''OTHER'')','ck_sku_currency|`currency` = ''CNY''','ck_sales_order_status_cancel|`order_status` IN (''CREATED'', ''PAID'', ''CANCELLED'', ''PARTIALLY_REFUNDED'', ''REFUNDED'')','ck_sales_order_amount_formula|`payable_amount` = `original_amount` - `product_discount_amount` - `coupon_discount_amount`','ck_sales_order_item_original_amount|`original_amount` = `unit_original_price` * `quantity`','ck_sales_order_item_amount_formula|`payable_amount` = `original_amount` - `product_discount_amount` - `coupon_discount_amount`','ck_payment_attempt_status_terminal|`payment_status` = ''SUCCESS''','ck_return_order_status_terminal|`return_status` = ''COMPLETED''','ck_refund_attempt_status_terminal|`refund_status` = ''SUCCESS''','ck_user_coupon_status_times|`coupon_status` = ''USED''')

Assert-Contract (-not ($ddlWithoutComments -match '(?is)FOREIGN_KEY_CHECKS|\bTRIGGER\b|\bPROCEDURE\b')) 'DDL contains a prohibited FK bypass, trigger, or stored procedure.'
$blocks = [regex]::Matches($ddl, '(?s)CREATE TABLE `(?<table>[a-z_]+)` \((?<body>.*?)\) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;')
Assert-Contract ($blocks.Count -eq 19) "Expected 19 CREATE TABLE blocks; found $($blocks.Count)."
$actualOrder = @($blocks | ForEach-Object { $_.Groups['table'].Value }); Assert-Contract (($actualOrder -join ',') -eq ($order -join ',')) 'CREATE TABLE order differs from DR-020.'
$fieldRows = [regex]::Matches($model, '(?m)^\| `(?<table>[a-z_]+)` \| `(?<field>[a-z0-9_]+)` \| `(?<type>[^`]+)` \| (?<nullable>是|否) \|'); $expectedFields = @{}
foreach ($row in $fieldRows) { $table = $row.Groups['table'].Value; if (-not $expectedFields.ContainsKey($table)) { $expectedFields[$table] = [System.Collections.Generic.List[object]]::new() }; $expectedFields[$table].Add([pscustomobject]@{ Name=$row.Groups['field'].Value; Type=$row.Groups['type'].Value; Nullable=$row.Groups['nullable'].Value }) }
Assert-Contract ($expectedFields.Keys.Count -eq 19) "Expected 19 field dictionaries; found $($expectedFields.Keys.Count)."
foreach ($block in $blocks) {
  $table = $block.Groups['table'].Value; $lines = $block.Groups['body'].Value -split "`r?`n"; $fields = @($lines | Where-Object { $_ -match '^  `(?<field>[a-z0-9_]+)` ' } | ForEach-Object { [regex]::Match($_, '^  `(?<field>[a-z0-9_]+)` (?<definition>.+?)(?:,)?$') })
  Assert-Contract ($expectedCounts.ContainsKey($table)) "Unexpected table: $table"; Assert-Contract ($fields.Count -eq $expectedCounts[$table]) "$table field count differs."
  if ($expectedFields.ContainsKey($table)) { $expected = $expectedFields[$table]; Assert-Contract ((@($fields | ForEach-Object { $_.Groups['field'].Value }) -join ',') -eq (($expected | ForEach-Object Name) -join ',')) "$table field names or order differ."; for ($i = 0; $i -lt [Math]::Min($fields.Count, $expected.Count); $i++) { $definition = $fields[$i].Groups['definition'].Value; Assert-Contract ($definition -match [regex]::Escape($expected[$i].Type)) "$table.$($expected[$i].Name) type differs."; if ($expected[$i].Nullable -eq '否') { Assert-Contract ($definition -match '\bNOT NULL\b') "$table.$($expected[$i].Name) must be NOT NULL." } elseif ($expected[$i].Name -notmatch '^successful_') { Assert-Contract ($definition -match '\bNULL\b') "$table.$($expected[$i].Name) must allow NULL." } } }
  $primaryPattern = 'PRIMARY KEY \(`' + $table + '_pk`\)'; Assert-Contract ($block.Groups['body'].Value -match $primaryPattern) "$table primary key differs."
}
$expectedObjectNames = @([regex]::Matches($model, '`(?<name>(?:uq|ck|fk|idx)_[a-z0-9_]+)`') | ForEach-Object { $_.Groups['name'].Value } | Select-Object -Unique); Assert-Contract ($expectedObjectNames.Count -eq 164) 'Physical registry must expose 164 non-primary names.'; foreach ($name in $expectedObjectNames) { Assert-Contract ([regex]::Matches($ddl, [regex]::Escape($name)).Count -eq 1) "Named object $name must occur once." }
foreach ($name in $expectedFks.Keys) { $p = $expectedFks[$name].Split(','); $pattern = 'CONSTRAINT `' + $name + '` FOREIGN KEY \(`' + $p[0] + '`\) REFERENCES `' + $p[1] + '` \(`' + $p[2] + '`\) ON DELETE RESTRICT ON UPDATE RESTRICT'; Assert-Contract ([regex]::Matches($ddl, $pattern).Count -eq 1) "FK $name differs." }
foreach ($name in $expectedUnique.Keys) { $pattern = 'CONSTRAINT `' + $name + '` UNIQUE \(' + [regex]::Escape((Columns $expectedUnique[$name])) + '\)'; Assert-Contract ([regex]::Matches($ddl, $pattern).Count -eq 1) "UNIQUE $name columns differ." }
foreach ($name in $expectedIndexes.Keys) { $pattern = 'KEY `' + $name + '` \(' + [regex]::Escape((Columns $expectedIndexes[$name])) + '\)'; Assert-Contract ([regex]::Matches($ddl, $pattern).Count -eq 1) "INDEX $name columns differ." }
foreach ($name in $expectedChecks.Keys) { $pattern = '(?m)^\s*CONSTRAINT `' + $name + '` CHECK .*' + [regex]::Escape($expectedChecks[$name]); Assert-Contract ([regex]::Matches($ddl, $pattern).Count -eq 1) "CHECK $name is missing required logic." }
Assert-Contract ([regex]::Matches($ddl, 'successful_order_pk` BIGINT UNSIGNED GENERATED ALWAYS AS \(CASE WHEN `payment_status` = ''SUCCESS'' THEN `order_pk` ELSE NULL END\) VIRTUAL').Count -eq 1) 'payment_attempt generated column differs.'; Assert-Contract ([regex]::Matches($ddl, 'CONSTRAINT `uq_payment_attempt_successful_order` UNIQUE \(`successful_order_pk`\)').Count -eq 1) 'payment_attempt generated unique pairing differs.'; Assert-Contract ([regex]::Matches($ddl, 'successful_return_order_pk` BIGINT UNSIGNED GENERATED ALWAYS AS \(CASE WHEN `refund_status` = ''SUCCESS'' THEN `return_order_pk` ELSE NULL END\) VIRTUAL').Count -eq 1) 'refund_attempt generated column differs.'; Assert-Contract ([regex]::Matches($ddl, 'CONSTRAINT `uq_refund_attempt_successful_return_order` UNIQUE \(`successful_return_order_pk`\)').Count -eq 1) 'refund_attempt generated unique pairing differs.'
$rollbackMatch = [regex]::Match($ddl, '(?ms)^-- Rollback order: (?<items>.*?)(?=^$)'); Assert-Contract ($rollbackMatch.Success) 'DDL header must declare rollback order.'; if ($rollbackMatch.Success) { $rollback = (($rollbackMatch.Groups['items'].Value -replace '(?m)^--\s*', '') -replace '\s+', ' ').Trim().TrimEnd('.') -split '\s*,\s*'; $expectedRollback = @($order[($order.Count - 1)..0]); Assert-Contract (($rollback -join ',') -eq ($expectedRollback -join ',')) 'Rollback order must exactly reverse creation order.' }
if ($failures.Count -gt 0) { $failures | ForEach-Object { Write-Error $_ }; exit 1 }
Write-Output 'PASS: Candidate DDL matches the 19-table / 230-field M2.2 static contract.'
exit 0
